function DISMANTLE() 
local tool = game.Players.LocalPlayer.Character.Crowbar.Handle
for _,v in ipairs(workspace.Vehicles:GetDescendants()) do
if v:IsA("Part") then
firetouchinterest(v,tool,0)
firetouchinterest(v,tool,1)
end
end
end

local lib = loadstring(game:HttpGet("https://raw.githubusercontent.com/bloodball/-back-ups-for-libs/main/wizard"))();
local winvar = lib:NewWindow("sss");
local Tab = winvar:NewSection("thing");
local Ex1 = false
Tab:CreateToggle("Dismantle",function(n)
Ex1 = n
while Ex1 do task.wait(0.1)
pcall(function()
DISMANTLE()
end)
if Ex1 == false then break
end
end
end)

